const { fonte, janela, modo } = $json;
const versaoApi = 'v21.0';
const limite = modo === 'amostra' ? 500 : 5000;
const campos = ['campaign_id', 'campaign_name', 'date_start', 'spend', 'impressions', 'clicks', 'actions', 'action_values'].join(',');
const timeRange = encodeURIComponent(JSON.stringify({ since: janela.start, until: janela.end }));

return [{
  json: {
    inicio: Date.now(),
    versaoApi,
    fonte,
    url: `https://graph.facebook.com/${versaoApi}/${fonte.externalId}/insights?level=campaign&time_increment=1&time_range=${timeRange}&fields=${campos}&limit=${limite}`,
  },
}];

const contexto = $('Montar requisição').first().json;
const respostas = $input.all().map((item) => item.json);
const requests = respostas.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const falhaDeRede = respostas.find((resposta) => resposta.error);
if (falhaDeRede) {
  const detalhe = falhaDeRede.error?.message ?? String(falhaDeRede.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}` }]);
}

const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300));
if (recusada) {
  const erro = Array.isArray(recusada.body) ? recusada.body[0]?.error : recusada.body?.error;
  const detalhe = erro?.message || `HTTP ${recusada.statusCode}`;
  const semAcesso = recusada.statusCode === 401 || recusada.statusCode === 403 || erro?.code === 190;
  return devolver([], [{ causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe }]);
}

const corpos = respostas.map((resposta) => resposta.body);
const fonte = contexto.fonte;

function somarAcoes(lista, tipo) {
  const item = (lista ?? []).find((acao) => acao.action_type === tipo);
  return item ? Number(item.value ?? 0) : 0;
}

const linhas = corpos.flatMap((corpo) => corpo?.data ?? []).map((linha) => ({
  externalCampaignId: String(linha.campaign_id ?? ''),
  campaignName: linha.campaign_name ?? null,
  metricDate: linha.date_start ?? null,
  spend: Number(linha.spend ?? 0),
  impressions: Number(linha.impressions ?? 0),
  clicks: Number(linha.clicks ?? 0),
  conversions: somarAcoes(linha.actions, 'purchase') || somarAcoes(linha.actions, 'offsite_conversion.fb_pixel_purchase'),
  revenue: somarAcoes(linha.action_values, 'purchase') || somarAcoes(linha.action_values, 'offsite_conversion.fb_pixel_purchase'),
  currency: fonte.currency || 'BRL',
}));

if (linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas, []);
